require_once __DIR__.'/../../includes/auth.php';require_once __DIR__.'/../../includes/ol_schema.php';$db=db();$error='';$message='';$subjects=$db->query("SELECT id,name_en FROM subjects WHERE status='active' ORDER BY name_en")->fetch_all(MYSQLI_ASSOC);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$sid=(int)($_POST['subject_id']??0);$year=(int)($_POST['year']??0);$medium=$_POST['medium']??'';if(!$sid||$year<2005||$year>2100||!in_array($medium,['si','ta','en'],true))throw new RuntimeException('Check subject, year and medium.');$f=$_FILES['paper']??null;if(!$f||$f['error']!==UPLOAD_ERR_OK||strtolower(pathinfo($f['name'],PATHINFO_EXTENSION))!=='pdf')throw new RuntimeException('Question paper must be a PDF.');$root=__DIR__.'/../../uploads/ol-papers';$dir=$root.'/'.$sid.'/'.$year.'/'.$medium;if(!is_dir($dir))mkdir($dir,0775,true);$name='paper_'.bin2hex(random_bytes(8)).'.pdf';$path=$dir.'/'.$name;if(!move_uploaded_file($f['tmp_name'],$path))throw new RuntimeException('Upload failed.');$answerPath=null;$a=$_FILES['answers']??null;if($a&&$a['error']===UPLOAD_ERR_OK){if(strtolower(pathinfo($a['name'],PATHINFO_EXTENSION))!=='pdf')throw new RuntimeException('Answer sheet must be a PDF.');$answerPath=$dir.'/answers_'.bin2hex(random_bytes(8)).'.pdf';if(!move_uploaded_file($a['tmp_name'],$answerPath))throw new RuntimeException('Answer upload failed.');}$rel='uploads/ol-papers/'.$sid.'/'.$year.'/'.$medium.'/'.$name;$arel=$answerPath?'uploads/ol-papers/'.$sid.'/'.$year.'/'.$medium.'/'.basename($answerPath):null;$st=$db->prepare('INSERT INTO ol_papers(subject_id,year,medium,paper_file_path,answer_sheet_path,uploaded_by) VALUES(?,?,?,?,?,?) ON DUPLICATE KEY UPDATE paper_file_path=VALUES(paper_file_path),answer_sheet_path=COALESCE(VALUES(answer_sheet_path),answer_sheet_path),status=1');$uid=(int)($_SESSION['admin']['id']??0);$st->bind_param('iisssi',$sid,$year,$medium,$rel,$arel,$uid);$st->execute();$message='Paper uploaded.';}catch(Throwable $e){$error=$e->getMessage();}}
$pageTitle='Upload O/L paper';include __DIR__.'/../_top.php';?><section class="card"><h1>Upload O/L paper</h1><?php if($error):?><p class="alert error"><?=e($error)?></p><?php endif;?><?php if($message):?><p class="alert success"><?=e($message)?></p><?php endif;?><form method="post" enctype="multipart/form-data"><?=csrf_field()?><label>Subject<select name="subject_id" required><?php foreach($subjects as $s):?><option value="<?=$s['id']?>"><?=e($s['name_en'])?></option><?php endforeach;?></select></label><label>Year<select name="year"><?php for($y=2025;$y>=2005;$y--):?><option><?=$y?></option><?php endfor;?></select></label><label>Medium<select name="medium"><option value="si">Sinhala</option><option value="ta">Tamil</option><option value="en">English</option></select></label><label>Question paper PDF<input type="file" name="paper" accept="application/pdf" required></label><label>Answer sheet PDF (optional)<input type="file" name="answers" accept="application/pdf"></label><button class="good">Upload paper</button></form></section><?php include __DIR__.'/../../includes/footer.php';
